class Solution:
    def rearrangeArray(self, nums: List[int]) -> List[int]:
        nums.sort()
        n = len(nums)
        res = [0] * n
        mid = (n + 1) // 2
        for i in range(mid):
            res[2 * i] = nums[i]
        for i in range(n - mid):
            res[2 * i + 1] = nums[mid + i]
        return res

