class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size(), mid = (n + 1) / 2;
        vector<int> res(n);
        for (int i = 0; i < mid; i++) res[2 * i] = nums[i];
        for (int i = 0; i < n - mid; i++) res[2 * i + 1] = nums[mid + i];
        return res;
    }
};

